contracts/NetIntegratedERC721A.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import { ERC721A } from "erc721a/contracts/ERC721A.sol";
import { LibString } from "solady/utils/LibString.sol";

interface INet {
    function sendMessage(
        string calldata text,
        string calldata topic,
        bytes calldata data
    ) external;

    function sendMessageViaApp(
        address sender,
        string calldata text,
        string calldata topic,
        bytes calldata data
    ) external;
}

/// @title NetIntegratedERC721A
/// @notice ERC721A base that auto-posts mint & transfer activity to Net Protocol.
/// @dev The collection contract IS the Net "app": messages it emits are indexed
///      under this contract's address. Extend this contract and implement
///      generative art() + tokenURI().
abstract contract NetIntegratedERC721A is ERC721A {
    using LibString for uint256;
    using LibString for address;

    /// @notice Net Protocol contract — same address on all supported chains.
    INet public constant NET = INet(0x00000000B24D62781dB359b07880a105cD0b64e6);

    string internal constant TOPIC_MINT = "mint";
    string internal constant TOPIC_TRANSFER = "transfer";
    string internal constant TOPIC_BURN = "burn";
    /// @dev Chain-wide registry topic: one message per collection, posted at deploy.
    string internal constant TOPIC_COLLECTION = "nft-collection";

    /// @notice Mint price per token, in wei.
    uint256 public immutable price;
    /// @notice Hard cap on total supply. 0 = unlimited.
    uint256 public immutable maxSupply;
    /// @notice Max tokens a single wallet may mint via public mint(). 0 = unlimited.
    uint256 public immutable maxMintsPerWallet;
    /// @notice Max tokens the deployer may ever mint via mintToCreator(). 0 = none.
    uint256 public immutable creatorReserve;
    /// @notice Tokens minted so far via mintToCreator().
    uint256 public creatorMinted;

    /// @notice Creator receiving mint revenue and controlling creator-only settings.
    /// Explicit because a CREATE2 deployment factory is not the collection creator.
    address public immutable creator;

    /// @notice Per-token entropy for generative art.
    mapping(uint256 => bytes32) internal _tokenToSeed;

    error IncorrectPayment();
    error MaxSupplyReached();
    error MaxMintsPerWalletReached();
    error CreatorReserveExceeded();
    error NotDeployer();
    error NetProtocolUnavailable();
    error InvalidCreator();

    modifier onlyDeployer() {
        if (msg.sender != creator) revert NotDeployer();
        _;
    }

    constructor(
        string memory name_,
        string memory symbol_,
        uint256 price_,
        uint256 maxSupply_,
        uint256 maxMintsPerWallet_,
        uint256 creatorReserve_,
        address creator_
    ) ERC721A(name_, symbol_) {
        if (creator_ == address(0)) revert InvalidCreator();
        creator = creator_;
        price = price_;
        maxSupply = maxSupply_;
        maxMintsPerWallet = maxMintsPerWallet_;
        creatorReserve = creatorReserve_;

        // A collection claiming Net integration must not deploy without it.
        if (address(NET).code.length == 0) revert NetProtocolUnavailable();
        NET.sendMessage(name_, TOPIC_COLLECTION, abi.encodePacked(creator_));
    }

    /// @dev Token IDs start at 1.
    function _startTokenId() internal pure virtual override returns (uint256) {
        return 1;
    }

    // ---------------------------------------------------------------- minting

    /// @notice Public paid mint.
    function mint(uint256 amount) external payable {
        if (msg.value != amount * price) revert IncorrectPayment();
        if (
            maxMintsPerWallet != 0 &&
            _numberMinted(msg.sender) + amount > maxMintsPerWallet
        ) revert MaxMintsPerWalletReached();

        _mintSeeded(msg.sender, amount);
    }

    /// @notice Free premint controlled by the creator, capped at creatorReserve.
    function mintToCreator(uint256 amount, address to) external onlyDeployer {
        if (creatorMinted + amount > creatorReserve) revert CreatorReserveExceeded();
        creatorMinted += amount;
        _mintSeeded(to, amount);
    }

    function _mintSeeded(address to, uint256 amount) internal virtual {
        _enforceSupply(amount);
        uint256 startTokenId = _nextTokenId();
        _seed(startTokenId, amount);
        _mint(to, amount);
        _afterMintSeeded(startTokenId, amount);
    }

    function _afterMintSeeded(uint256 startTokenId, uint256 amount) internal virtual {}

    function _enforceSupply(uint256 amount) internal view {
        if (maxSupply != 0 && _totalMinted() + amount > maxSupply) {
            revert MaxSupplyReached();
        }
    }

    /// @dev Assign per-token seeds.
    function _seed(uint256 startTokenId, uint256 amount) internal virtual {
        unchecked {
            for (uint256 i; i < amount; ++i) {
                _tokenToSeed[startTokenId + i] =
                    keccak256(abi.encodePacked(block.prevrandao, startTokenId + i));
            }
        }
    }

    // ------------------------------------------------------------ withdrawals

    /// @notice Withdraw collected ETH to the creator.
    function withdraw() external {
        (bool ok, ) = creator.call{ value: address(this).balance }("");
        require(ok);
    }

    // ------------------------------------------------------- Net integration

    function _afterTokenTransfers(
        address from,
        address to,
        uint256 startTokenId,
        uint256 quantity
    ) internal virtual override {
        uint256 endTokenId = startTokenId + quantity - 1;

        address msgSender;
        string memory topic;
        string memory text;
        if (from == address(0)) {
            msgSender = to;
            topic = TOPIC_MINT;
            text = _mintText(to, startTokenId, endTokenId);
        } else if (to == address(0)) {
            msgSender = from;
            topic = TOPIC_BURN;
            text = _burnText(from, startTokenId, endTokenId);
        } else {
            msgSender = from;
            topic = TOPIC_TRANSFER;
            text = _transferText(from, to, startTokenId, endTokenId);
        }

        NET.sendMessageViaApp(msgSender, text, topic, "");
    }

    function _mintText(address to, uint256 startId, uint256 endId)
        internal
        view
        virtual
        returns (string memory)
    {
        return string.concat(
            "Minted #", startId.toString(), "-#", endId.toString(),
            " to ", to.toHexString()
        );
    }

    function _transferText(address from, address to, uint256 startId, uint256 endId)
        internal
        view
        virtual
        returns (string memory)
    {
        return string.concat(
            "Transferred #", startId.toString(), "-#", endId.toString(),
            " from ", from.toHexString(), " to ", to.toHexString()
        );
    }

    function _burnText(address from, uint256 startId, uint256 endId)
        internal
        view
        virtual
        returns (string memory)
    {
        return string.concat(
            "Burned #", startId.toString(), "-#", endId.toString(),
            " by ", from.toHexString()
        );
    }
}

contracts/TinyFrensArt.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {LibString} from "solady/utils/LibString.sol";
import {TinyFrensSprite} from "./TinyFrensSprite.sol";

struct Traits {
    uint8 species;
    uint8 palette;
    uint8 expr;
    uint8 acc;
    uint8 era;
    uint8 habitat;
    uint8 motion;
    uint16 ambience;
}

interface ITinyFrensArt {
    function render(Traits calldata traits, uint8 stage) external view returns (string memory);
}

contract TinyFrensArt is ITinyFrensArt {
    using LibString for uint256;

    TinyFrensSprite public immutable spriteRenderer;

    constructor(address spriteRenderer_) {
        require(spriteRenderer_.code.length > 0, "Missing sprite renderer");
        spriteRenderer = TinyFrensSprite(spriteRenderer_);
    }

    function _box(uint256 x, uint256 y, uint256 width, uint256 height, string memory color)
        internal pure returns (string memory)
    {
        width = (x + width) * 3 / 2 - x * 3 / 2;
        height = (y + height) * 3 / 2 - y * 3 / 2;
        x = x * 3 / 2;
        y = y * 3 / 2;
        return string.concat('<path fill="', color, '" d="M', x.toString(), ' ', y.toString(),
            'h', width.toString(), 'v', height.toString(), 'H', x.toString(), 'z"/>');
    }

    function _palette(uint8 palette) internal pure returns (string memory body, string memory ink, string memory bg) {
        if (palette == 0) return ("#a474f1", "#302048", "#17142a");
        if (palette == 1) return ("#66c7d2", "#183d4d", "#102c38");
        if (palette == 2) return ("#ffb95e", "#623b29", "#382a38");
        if (palette == 3) return ("#82eba1", "#24533f", "#193c3a");
        if (palette == 4) return ("#ff82a7", "#632b48", "#3b213b");
        if (palette == 5) return ("#4d96ff", "#263a6a", "#182d50");
        if (palette == 6) return ("#76638e", "#241d38", "#211c39");
        return ("#ffd700", "#6c421c", "#2d2238");
    }

    // Seven bytes per tile: x, y, width, height, RGB. Consecutive fills share an SVG path.
    function _scene(bytes memory data, string memory bg) internal pure returns (string memory result) {
        uint256 previous = type(uint256).max;
        string memory path;
        string memory color;
        for (uint256 i; i < data.length; i += 7) {
            uint256 rgb = (uint256(uint8(data[i + 4])) << 16)
                | (uint256(uint8(data[i + 5])) << 8) | uint256(uint8(data[i + 6]));
            if (rgb != previous) {
                if (bytes(path).length != 0) result = string.concat(result, '<path fill="', color, '" d="', path, '"/>');
                path = "";
                color = rgb == 0 ? bg : string.concat("#", LibString.toHexStringNoPrefix(rgb, 3));
                previous = rgb;
            }
            path = string.concat(path, "M", uint256(uint8(data[i])).toString(), " ",
                uint256(uint8(data[i + 1])).toString(), "h", uint256(uint8(data[i + 2])).toString(),
                "v", uint256(uint8(data[i + 3])).toString(), "h-", uint256(uint8(data[i + 2])).toString(), "z");
        }
        if (bytes(path).length != 0) result = string.concat(result, '<path fill="', color, '" d="', path, '"/>');
    }

    // Generated from web/robot-scenes.mjs by scripts/sync-robot-scenes.mjs.
    function _habitat(uint8 habitat, string memory bg) internal pure returns (string memory) {
        if (habitat == 0) return string.concat(
            _scene(hex"", bg),
            string.concat('<g class="parallax">', _scene(hex"1f41091d2d2b462b3b07232d2b46523f0a1f2d2b465e4607182d2b46", bg), '</g>'),
            _scene(hex"", bg),
            string.concat('<g class="twinkle">', _scene(hex"16230105bba2d814250501bba2d816250101ffffff4e090103e9daff4d0a0301e9daff", bg), '</g>'),
            string.concat('<g class="twinkle late">', _scene(hex"720c0105bba2d8700e0501bba2d8720e0101ffffff28090103e9daff270a0301e9daff", bg), '</g>'),
            string.concat('<g class="drift">', _scene(hex"261614027066812b140b0287788e271811014f506a", bg), '</g>'),
            string.concat('<g class="light">', _scene(hex"5e6322049cabe052672e059cabe0466d3a069cabe0397347069cabe02b7a55069cabe0", bg), '</g>')
        );
        if (habitat == 1) return string.concat(
            _scene(hex"", bg),
            string.concat('<g class="parallax">', _scene(hex"242d0c311c29413323093b1c294144300a2e1c294151280a361c2941", bg), '</g>'),
            _scene(hex"", bg),
            string.concat('<g class="glow">', _scene(hex"6c200608b1fff1062e0608ffc3e3", bg), '</g>'),
            string.concat('<g class="glow late">', _scene(hex"087810028dd6df68780c02d89fc7", bg), '</g>'),
            string.concat('<g class="drift">', _scene(hex"261614027066812b140b0287788e271811014f506a", bg), '</g>'),
            string.concat('<g class="light">', _scene(hex"04651304ec9cce07741402ec9cce027b1c02ec9cce68661803ec9cce63791d03ec9cce", bg), '</g>')
        );
        if (habitat == 2) return string.concat(
            _scene(hex"", bg),
            string.concat('<g class="parallax">', _scene(hex"284f0f0f4c6054394a12144c60544e510e0d4c6054", bg), '</g>'),
            _scene(hex"", bg),
            string.concat('<g class="sway">', _scene(hex"703a020ab4d9956a3a080495c8837236080495c883", bg), '</g>'),
            string.concat('<g class="leaf">', _scene(hex"101e0402cbd5831420020282b97c", bg), '</g>'),
            string.concat('<g class="leaf late">', _scene(hex"6c140402efca8270160202a6bd78", bg), '</g>'),
            string.concat('<g class="drift">', _scene(hex"261614027066812b140b0287788e271811014f506a", bg), '</g>'),
            string.concat('<g class="light">', _scene(hex"00621b05ffe0ac00672005ffe0ac006c2506ffe0ac00722b07ffe0ac00793207ffe0ac", bg), '</g>')
        );
        if (habitat == 3) return string.concat(
            _scene(hex"", bg),
            string.concat('<g class="parallax">', _scene(hex"003b0b2566647f0e41091f66647f1a340c2c66647f293d0a2366647f362e093266647f423a0d2666647f5233092d66647f5e420c1e66647f6e38092866647f793f072166647f004911174b4c6a15460c1a4b4c6a284e0d124b4c6a3d450e1b4b4c6a504b0e154b4c6a63470c194b4c6a744f0c114b4c6a3b2a0204b8a7bb3b32011e91b7cb54370206d0b8bf", bg), '</g>'),
            string.concat('<g class="drift">', _scene(hex"08171a03c7b1c20c131104e9c9c511100803e9c9c50a1a1601978da9", bg), '</g>'),
            string.concat('<g class="drift late">', _scene(hex"4e222303c7b1c2531e1904e9c9c5591b0d03e9c9c550251f01978da9", bg), '</g>'),
            string.concat('<g class="glow">', _scene(hex"094f0501a5ffff3f49020399d9df454e020399d9df2b51020399d9df", bg), '</g>'),
            string.concat('<g class="sway">', _scene(hex"6d530a034b807b6b4f0e04659c886e4b09048eb2966f4b0302c3c6a276500302b9c29d", bg), '</g>'),
            string.concat('<g class="light">', _scene(hex"5e632204ffe0ac52672e05ffe0ac466d3a06ffe0ac39734706ffe0ac2b7a5506ffe0ac", bg), '</g>')
        );
        if (habitat == 4) return string.concat(
            _scene(hex"", bg),
            string.concat('<g class="parallax">', _scene(hex"1e28063730253e5a28063730253e24283601503654", bg), '</g>'),
            _scene(hex"", bg),
            string.concat('<g class="glow">', _scene(hex"08400404d2ffe81a181002ffc0dd", bg), '</g>'),
            string.concat('<g class="glow late">', _scene(hex"703a0604ffe5a156181002b2fff6", bg), '</g>'),
            string.concat('<g class="light">', _scene(hex"03661305ec9cce076b1405ec9cce0b701605ec9cce69671405ec9cce626c1907ec9cce", bg), '</g>')
        );
        return string.concat(
            _scene(hex"", bg),
            string.concat('<g class="parallax">', _scene(hex"144f19074b796124491e0d4b79613b4d1e094b7961525114054b7961", bg), '</g>'),
            _scene(hex"", bg),
            string.concat('<g class="drift">', _scene(hex"06181806ccbdce0c140c04ccbdce", bg), '</g>'),
            string.concat('<g class="drift late">', _scene(hex"5e0e1c06ccbdce660a0c04ccbdce", bg), '</g>'),
            string.concat('<g class="sway">', _scene(hex"003e0e028caf796c380e028caf79", bg), '</g>'),
            string.concat('<g class="leaf">', _scene(hex"0e280402e8ce83122a02029bbd77", bg), '</g>'),
            string.concat('<g class="leaf late">', _scene(hex"6e200402b5d1916c22020278a36d", bg), '</g>'),
            string.concat('<g class="light">', _scene(hex"60622005ffe0ac5a672605ffe0ac516c2f06ffe0ac49723707ffe0ac3f794107ffe0ac", bg), '</g>')
        );
    }

    function _accessory(uint8 accessory, uint8) internal pure returns (string memory) {
        if (accessory == 0) return _scene(hex"2e1203093020482b0f0904f0bd5e2e0d0302ffe078", "");
        if (accessory == 1) return _scene(hex"1e18240324344f21121e066e8da9250f1503a9c7d622120504d1e3e8271313034bd2dc28130802c1f6ef2e0f0303f1d18a3a160502324f6c", "");
        if (accessory == 2) return _scene(hex"21181e0379503822121b06c18b3c210f0409e6b54f3a0f0509e6b54f2d0d060be6b54f25150803e6b54f33150703e6b54f22181b01ffe3a022100206ffe3a02d0f0104ffe3a02816030275d0d734160302e38eac2e1503039555a1", "");
        if (accessory == 3) return string.concat('<g class="halo">', _scene(hex"250f1501bd874221100402bd87423a100502bd87421f120504bd87423c120404bd874222161b02bd874225181501bd874225101502fff1bd21120303fff1bd3c120303f1c86c24151803f1c86c27151201fff4d4", ""), '</g>');
        if (accessory == 4) return _scene(hex"2e1203093020482b0f0904f0bd5e2e0d0302ffe078243c1801e1d7cf243d060684324f363d060684324f253d0505ef79962a3f0403cf526f313f0503cf526f363d0405ef7996253d0302ffb0b8373d0302ffb0b82e3f0303e9c371", "");
        if (accessory == 5) return string.concat(_scene(hex"2e1203093020482b0f0904f0bd5e2e0d0302ffe078", ""), '<g class="orb">', _scene(hex"522106012447624f220c032447624e250f062447624f2b0c03244762522e0602244762522206029aede45124090750b5ca522b0602387b9e512503059aede45424040474d9dc572803033785aa52240301ecfff2", ""), '</g>');
        return "";
    }

    function _eraMark(uint8 era) internal pure returns (string memory) {
        if (era == 0) return _box(23, 39, 2, 1, "#dc9979");
        if (era == 1) return string.concat(_box(23, 39, 2, 1, "#b9c5dc"), _box(27, 39, 2, 1, "#b9c5dc"));
        return string.concat(_box(23, 39, 2, 1, "#ffe078"), _box(27, 39, 2, 1, "#ffe078"),
            _box(31, 39, 2, 1, "#ffe078"));
    }

    function render(Traits calldata traits, uint8 stage) external view override returns (string memory) {
        (string memory body, string memory ink, string memory bg) = _palette(traits.palette);
        string memory sprite = spriteRenderer.render(traits.species, body, ink, traits.expr);
        string memory duration = traits.motion == 1 ? "0.8471s" : traits.motion == 2 ? "1.8824s" :
            traits.motion == 3 ? "0.6588s" : "1.1294s";
        string memory phase = traits.motion == 1 ? "-0.42355s" : traits.motion == 2 ? "-0.9412s" :
            traits.motion == 3 ? "-0.3294s" : "-0.5647s";
        string memory style = string.concat(
            '<style>', spriteRenderer.motionStyle(traits.ambience), '.body{animation:bob ', duration, ' steps(1) infinite}',
            '.foot-a{animation:step-a ', duration, ' steps(1) infinite}',
            '.foot-b{animation:step-a ', duration, ' steps(1) infinite;animation-delay:', phase, '}',
            '.arm-a{animation:arm-a ', duration, ' steps(1) infinite}',
            '.arm-b{animation:arm-a ', duration, ' steps(1) infinite;animation-delay:', phase, '}',
            '@keyframes bob{0%,50%,100%{transform:translateY(0)}12.5%,37.5%,62.5%,87.5%{transform:translateY(-1px)}25%,75%{transform:translateY(0)}}',
            '@keyframes step-a{0%,100%{transform:translate(-1px,0)}12.5%{transform:translate(0,-1px)}25%{transform:translate(1px,-2px)}37.5%{transform:translate(2px,-1px)}50%{transform:translate(2px,0)}62.5%{transform:translate(1px,0)}75%{transform:translate(0,0)}87.5%{transform:translate(-1px,0)}}',
            '@keyframes arm-a{0%,100%{transform:translate(1px,0)}25%{transform:translate(-1px,1px)}50%{transform:translate(-1px,0)}75%{transform:translate(1px,-1px)}}',
            spriteRenderer.sceneryStyle(),
            '@media(prefers-reduced-motion:reduce){.body,.foot-a,.foot-b,.arm-a,.arm-b,.drift,.twinkle,.glow,.sway,.leaf,.shadow,.parallax,.light,.sheen,.orb,.halo{animation:none}}</style>'
        );
        string memory evolution = stage == 0 ? "" :
            string.concat(_box(4, 4, 2, 2, "#ffe078"), _box(57, 9, 2, 2, "#ffe078"));
        return string.concat(
            '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 128 128" width="100%" height="100%" shape-rendering="crispEdges" data-species="',
            uint256(traits.species).toString(), '">',
            style, _habitat(traits.habitat, bg), '<g transform="translate(16 30)"><g class="shadow">', _box(17, 50, 32, 2, "#17212d"), '</g>',
            sprite, '<g class="body">', _accessory(traits.acc, traits.species), _eraMark(traits.era), '</g></g>',
            evolution, '</svg>'
        );
    }
}

contracts/TinyFrensNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import { NetIntegratedERC721A } from "./NetIntegratedERC721A.sol";
import { LibString } from "solady/utils/LibString.sol";
import { Base64 } from "solady/utils/Base64.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { ITinyFrensArt, Traits } from "./TinyFrensArt.sol";

interface INetStorage {
    function put(bytes32 key, string calldata text, bytes calldata data) external;
    function get(bytes32 key, address operator) external view returns (string memory, bytes memory);
}

/// @title TinyFrensNFT
/// @notice Curated on-chain companion collection with FRENS Piggybank Vault backing.
///         Auto-posts mints, transfers, and burns to Net Protocol.
contract TinyFrensNFT is NetIntegratedERC721A {
    using LibString for uint256;
    using SafeERC20 for IERC20;

    string public constant COLLECTION_ID = "tinyfrens-robots-v1";
    string public constant COLLECTION_NAME = "TinyFrens: Robots v1";
    string public constant COLLECTION_SYMBOL = "TFROB1";
    string public constant TOKEN_NAME_PREFIX = "TinyFrens Robot v1 #";
    string public constant COLLECTION_DESCRIPTION = "TinyFrens: Robots v1. An on-chain robot companion collection with animated pixel artwork.";
    uint8 public constant COLLECTION_VERSION = 1;

    ITinyFrensArt public immutable artRenderer;
    IERC20 public frensToken;
    uint256 public frensPerVaultMint;
    mapping(uint256 => uint256) public lockedFrens;

    mapping(uint256 => string) private _customName;
    mapping(uint256 => uint8) private _evolution;

    INetStorage public constant NET_STORAGE = INetStorage(0x00000000DB40fcB9f4466330982372e27Fd7Bbf5);

    event TinyFrenRenamed(uint256 indexed tokenId, string name);
    event TinyFrenEvolved(uint256 indexed tokenId, uint8 stage);
    event TinyFrenNetStorageSynced(uint256 indexed tokenId, address indexed operator, bytes32 indexed key);
    event TinyFrenVaultMinted(uint256 indexed tokenId, address indexed owner, uint256 frensLocked);
    event TinyFrenUnwrapped(uint256 indexed tokenId, address indexed owner, uint256 frensRedeemed);
    event FrensPerVaultMintUpdated(uint256 frensPerVaultMint);
    event FrensTokenUpdated(address frensToken);

    error InvalidPetName();
    error MaxEvolutionReached();
    error NotTokenOwner();
    error NoLockedFrens();
    error InsufficientFrensDeposit();
    error ZeroAddress();
    error NetStorageUnavailable();
    error NetStorageMetadataMissing();

    constructor(address artRenderer_, address creator_)
        NetIntegratedERC721A(
            COLLECTION_NAME,
            COLLECTION_SYMBOL,
            0.001 ether, // price (0.001 ETH)
            2664,        // maxSupply
            20,          // maxMintsPerWallet
            20,          // creatorReserve
            creator_
        )
    {
        require(artRenderer_.code.length > 0, "Missing art renderer");
        if (address(NET_STORAGE).code.length == 0) revert NetStorageUnavailable();
        artRenderer = ITinyFrensArt(artRenderer_);
        frensToken = IERC20(0x1A96226727a1D0a46334b3A4b3878B32B7659ba3);
        frensPerVaultMint = 47_619_047 * 10**18; // ~0.002 ETH worth of FRENS
    }

    function setFrensToken(address newToken) external onlyDeployer {
        if (newToken == address(0)) revert ZeroAddress();
        frensToken = IERC20(newToken);
        emit FrensTokenUpdated(newToken);
    }

    function setFrensPerVaultMint(uint256 newAmount) external onlyDeployer {
        frensPerVaultMint = newAmount;
        emit FrensPerVaultMintUpdated(newAmount);
    }

    /// @notice Mint Fren Vault loaded with FRENS tokens (0.002 ETH worth of FRENS)
    function mintWithVault(uint256 amount, uint256 frensPerToken) external {
        if (address(frensToken) == address(0)) revert ZeroAddress();
        if (frensPerVaultMint != 0 && frensPerToken < frensPerVaultMint) revert InsufficientFrensDeposit();
        if (
            maxMintsPerWallet != 0 &&
            _numberMinted(msg.sender) + amount > maxMintsPerWallet
        ) revert MaxMintsPerWalletReached();

        uint256 totalFrens = amount * frensPerToken;
        frensToken.safeTransferFrom(msg.sender, address(this), totalFrens);

        uint256 startTokenId = _nextTokenId();
        _mintSeeded(msg.sender, amount);

        unchecked {
            for (uint256 i; i < amount; ++i) {
                uint256 tid = startTokenId + i;
                lockedFrens[tid] = frensPerToken;
                _syncNetStorage(tid);
                emit TinyFrenVaultMinted(tid, msg.sender, frensPerToken);
            }
        }
    }

    /// @notice Deposit additional FRENS collateral into an existing Fren NFT
    function depositFrens(uint256 tokenId, uint256 amount) external {
        if (!_exists(tokenId)) revert URIQueryForNonexistentToken();
        if (amount == 0) revert InsufficientFrensDeposit();
        frensToken.safeTransferFrom(msg.sender, address(this), amount);
        lockedFrens[tokenId] += amount;
        _syncNetStorage(tokenId);
        emit TinyFrenVaultMinted(tokenId, ownerOf(tokenId), lockedFrens[tokenId]);
    }

    /// @notice Unwrap Fren Vault: burns NFT and returns 100% of locked FRENS to the owner
    function unwrap(uint256 tokenId) external {
        _requireTokenOwner(tokenId);
        uint256 locked = lockedFrens[tokenId];
        if (locked == 0) revert NoLockedFrens();

        delete lockedFrens[tokenId];
        _burn(tokenId);
        frensToken.safeTransfer(msg.sender, locked);

        emit TinyFrenUnwrapped(tokenId, msg.sender, locked);
    }

    function tokenName(uint256 tokenId) public view returns (string memory) {
        if (!_exists(tokenId)) revert URIQueryForNonexistentToken();
        string memory custom = _customName[tokenId];
        if (bytes(custom).length != 0) return custom;
        return string.concat(TOKEN_NAME_PREFIX, tokenId.toString());
    }

    function evolutionStage(uint256 tokenId) public view returns (uint8) {
        if (!_exists(tokenId)) revert URIQueryForNonexistentToken();
        return _evolution[tokenId];
    }

    function rename(uint256 tokenId, string calldata newName) external {
        _requireTokenOwner(tokenId);
        bytes calldata raw = bytes(newName);
        if (raw.length == 0 || raw.length > 32) revert InvalidPetName();
        for (uint256 i; i < raw.length; ++i) {
            bytes1 c = raw[i];
            bool ok = (c >= 0x30 && c <= 0x39) || (c >= 0x41 && c <= 0x5A) || (c >= 0x61 && c <= 0x7A)
                || c == 0x20 || c == 0x21 || c == 0x23 || c == 0x2D || c == 0x2E || c == 0x3F || c == 0x5F;
            if (!ok) revert InvalidPetName();
        }
        _customName[tokenId] = newName;
        _syncNetStorage(tokenId);
        emit TinyFrenRenamed(tokenId, newName);
    }

    function evolve(uint256 tokenId) external {
        _requireTokenOwner(tokenId);
        uint8 stage = _evolution[tokenId];
        if (stage >= 3) revert MaxEvolutionReached();
        unchecked {
            stage += 1;
        }
        _evolution[tokenId] = stage;
        _syncNetStorage(tokenId);
        emit TinyFrenEvolved(tokenId, stage);
    }

    function netStoragePointer(uint256 tokenId)
        external
        view
        returns (address operator, bytes32 key, string memory text)
    {
        if (!_exists(tokenId)) revert URIQueryForNonexistentToken();
        return (address(this), _netStorageKey(tokenId), _netStorageText(tokenId));
    }

    function _requireTokenOwner(uint256 tokenId) internal view {
        if (!_exists(tokenId)) revert URIQueryForNonexistentToken();
        if (ownerOf(tokenId) != msg.sender) revert NotTokenOwner();
    }

    function _afterMintSeeded(uint256 startTokenId, uint256 amount) internal override {
        unchecked {
            for (uint256 i; i < amount; ++i) {
                _syncNetStorage(startTokenId + i);
            }
        }
    }

    function _netStorageKey(uint256 tokenId) internal view returns (bytes32) {
        return keccak256(abi.encodePacked("tinyfrens.tokenURI", address(this), tokenId));
    }

    function _netStorageText(uint256 tokenId) internal pure returns (string memory) {
        return string.concat(COLLECTION_NAME, " tokenURI #", tokenId.toString());
    }

    function _syncNetStorage(uint256 tokenId) internal {
        bytes32 key = _netStorageKey(tokenId);
        NET_STORAGE.put(key, _netStorageText(tokenId), bytes(_generatedTokenURI(tokenId)));
        emit TinyFrenNetStorageSynced(tokenId, address(this), key);
    }

    function _traits(uint256 tokenId) internal pure returns (Traits memory t) {
        // BNKR launch is a focused robot-only collection across three 888-token eras.
        t.species = 0;

        t.era = uint8((tokenId - 1) / 888);
        uint256 cohortIndex = (tokenId - 1) % 888;
        uint256 artIndex = (cohortIndex * 197 + 17) % 4608;
        t.palette = uint8(artIndex % 8);
        uint256 combination = artIndex / 8;
        t.expr = uint8(combination % 4);
        t.acc = uint8((combination / 4) % 6);
        t.habitat = uint8((combination / 24) % 6);
        t.motion = uint8((combination / 144) % 4);
        t.ambience = uint16((tokenId * 7919 + 104729) % 65536);
    }

    function _speciesName(uint8) internal pure returns (string memory) {
        return "Robot";
    }

    function _paletteData(uint8 p) internal pure returns (
        string memory body,
        string memory dark,
        string memory bg,
        string memory name,
        string memory tier
    ) {
        if (p == 0) return ("#a474f1", "#302048", "#17142a", "Lavender Dream", "Classic");
        if (p == 1) return ("#66c7d2", "#183d4d", "#102c38", "Cyber Neon", "Classic");
        if (p == 2) return ("#ffb95e", "#623b29", "#382a38", "Sunny Amber", "Classic");
        if (p == 3) return ("#82eba1", "#24533f", "#193c3a", "Mint Meadow", "Classic");
        if (p == 4) return ("#ff82a7", "#632b48", "#3b213b", "Bubblegum", "Classic");
        if (p == 5) return ("#4d96ff", "#263a6a", "#182d50", "Electric Blue", "Classic");
        if (p == 6) return ("#76638e", "#241d38", "#211c39", "Midnight Obsidian", "Rare");
        return ("#ffd700", "#6c421c", "#2d2238", "24K Solid Gold", "Legendary");
    }

    function _exprName(uint8 e) internal pure returns (string memory) {
        if (e == 0) return "Classic Happy";
        if (e == 1) return "Playful Wink";
        if (e == 2) return "Cool Shades";
        return "Star Eyes";
    }

    function _accName(uint8 a) internal pure returns (string memory) {
        if (a == 0) return "None";
        if (a == 1) return "Pilot Helmet";
        if (a == 2) return "Royal Crown";
        if (a == 3) return "Angel Halo";
        if (a == 4) return "Dapper Bow Tie";
        return "Mystic Orb";
    }

    function _eraName(uint8 e) internal pure returns (string memory) {
        if (e == 0) return "Pocket Genesis";
        if (e == 1) return "Street Wanderers";
        return "Dream Garden";
    }

    function _habitatName(uint8 h) internal pure returns (string memory) {
        if (h == 0) return "Moonlit Plaza";
        if (h == 1) return "Neon Crosswalk";
        if (h == 2) return "Snack Garden";
        if (h == 3) return "Cloud Terrace";
        if (h == 4) return "Arcade Alley";
        return "Tiny Meadow";
    }

    function _motionName(uint8 m) internal pure returns (string memory) {
        if (m == 0) return "Happy Walk";
        if (m == 1) return "Bouncy Strut";
        if (m == 2) return "Sleepy Drift";
        return "Excited Wiggle";
    }

    /// @notice 128x128 grid-drawn animated companion scene.
    function art(uint256 tokenId) public view returns (string memory) {
        if (!_exists(tokenId)) revert URIQueryForNonexistentToken();
        return artRenderer.render(_traits(tokenId), _evolution[tokenId]);
    }

    function _ambientName(uint8 family, uint8 variant) internal pure returns (string memory) {
        if (family == 0) return variant == 0 ? "Easy" : variant == 1 ? "Brisk" : variant == 2 ? "Swift" : "Lazy";
        if (family == 1) return variant == 0 ? "Sparkling" : variant == 1 ? "Lively" : variant == 2 ? "Soft" : "Dreamy";
        if (family == 2) return variant == 0 ? "Drifting" : variant == 1 ? "Breezy" : variant == 2 ? "Unhurried" : "Playful";
        if (family == 3) return variant == 0 ? "Gentle" : variant == 1 ? "Breezy" : variant == 2 ? "Calm" : "Lively";
        if (family == 4) return variant == 0 ? "Warm" : variant == 1 ? "Rolling" : variant == 2 ? "Lingering" : "Shimmering";
        if (family == 5) return variant == 0 ? "Pulsing" : variant == 1 ? "Lively" : variant == 2 ? "Mellow" : "Glowing";
        if (family == 6) return variant == 0 ? "Gentle" : variant == 1 ? "Wandering" : variant == 2 ? "Still Air" : "Breezy";
        if (family == 7) return variant == 0 ? "Buoyant" : variant == 1 ? "Bobbing" : variant == 2 ? "Dreamy" : "Gentle";
        revert("Invalid motion");
    }

    function _ambientKey(uint8 family) internal pure returns (string memory) {
        if (family == 0) return "Cloud Drift";
        if (family == 1) return "Star Twinkle";
        if (family == 2) return "Falling Leaves";
        if (family == 3) return "Foliage Sway";
        if (family == 4) return "Light Cycle";
        if (family == 5) return "Neon Glow";
        if (family == 6) return "Layer Drift";
        if (family == 7) return "Accessory Float";
        revert("Invalid motion");
    }

    function _ambientAttributes(Traits memory t) internal pure returns (string memory result) {
        for (uint8 i; i < 8; i++) {
            bool relevant = i == 0 ? t.habitat != 4 : i == 1 ? t.habitat == 0 :
                i == 2 ? t.habitat == 2 || t.habitat == 5 :
                i == 3 ? t.habitat == 2 || t.habitat == 3 || t.habitat == 5 :
                i == 5 ? t.habitat == 1 || t.habitat == 3 || t.habitat == 4 :
                i == 7 ? t.acc == 3 || t.acc == 5 : true;
            if (relevant) result = string.concat(result, ',{"trait_type":"', _ambientKey(i),
                '","value":"', _ambientName(i, uint8((t.ambience >> (i * 2)) & 3)), '"}');
        }
    }

    function _attributes(uint256 tokenId) internal view returns (string memory) {
        Traits memory t = _traits(tokenId);
        (, , , string memory palName, string memory tier) = _paletteData(t.palette);

        uint256 locked = lockedFrens[tokenId];
        string memory vaultAttrs = "";
        if (locked > 0) {
            vaultAttrs = string.concat(
                ',{"trait_type":"Vault Backed","value":"FRENS Piggybank"},{"trait_type":"Locked FRENS (Wei)","value":"',
                locked.toString(),
                '"}'
            );
        }

        return string.concat(
            '[{"trait_type":"Series","value":"Robots"},{"trait_type":"Edition","value":"v1"},{"trait_type":"Species","value":"', _speciesName(t.species),
            '"},{"trait_type":"Palette","value":"', palName,
            '"},{"trait_type":"Rarity Tier","value":"', tier,
            '"},{"trait_type":"Expression","value":"', _exprName(t.expr),
            '"},{"trait_type":"Accessory","value":"', _accName(t.acc),
            '"},{"trait_type":"Era","value":"', _eraName(t.era),
            '"},{"trait_type":"Habitat","value":"', _habitatName(t.habitat),
            '"},{"trait_type":"Motion","value":"', _motionName(t.motion),
            '"},{"trait_type":"Evolution","value":"Stage ', uint256(_evolution[tokenId]).toString(),
            '"}',
            _ambientAttributes(t), vaultAttrs,
            ']'
        );
    }

    function tokenURI(uint256 tokenId) public view virtual override returns (string memory) {
        if (!_exists(tokenId)) revert URIQueryForNonexistentToken();

        (, bytes memory data) = NET_STORAGE.get(_netStorageKey(tokenId), address(this));
        if (data.length == 0) revert NetStorageMetadataMissing();
        return string(data);
    }

    function contractURI() external pure returns (string memory) {
        return string.concat("data:application/json;base64,", Base64.encode(bytes(string.concat(
            '{"name":"', COLLECTION_NAME, '","description":"', COLLECTION_DESCRIPTION,
            '","external_link":"https://tinyfrens.lol"}'
        ))));
    }

    function _generatedTokenURI(uint256 tokenId) internal view returns (string memory) {
        string memory image = Base64.encode(bytes(art(tokenId)));
        string memory json = string.concat(
            '{"name":"', tokenName(tokenId),
            '","description":"', COLLECTION_DESCRIPTION, '",',
            '"image":"data:image/svg+xml;base64,', image, '",',
            '"attributes":', _attributes(tokenId),
            '}'
        );
        return string.concat("data:application/json;base64,", Base64.encode(bytes(json)));
    }
}

contracts/TinyFrensSprite.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {LibString} from "solady/utils/LibString.sol";

contract TinyFrensSprite {
    using LibString for uint256;

    // Fixed CSS lives beside sprite data to leave room for packed scene artwork.
    function sceneryStyle() external pure returns (string memory) {
        return '.orb,.halo{animation:hover var(--float) steps(4) infinite alternate}@keyframes hover{from{transform:translateY(0)}to{transform:translateY(-2px)}}.parallax{animation:parallax var(--depth) steps(4) infinite alternate}.light{animation:lighting var(--light) steps(4) infinite alternate}.sheen{animation:shade var(--light) steps(4) infinite alternate}.drift{animation:breeze var(--cloud) steps(10) infinite alternate}.twinkle{animation:sparkle var(--stars) steps(8) infinite alternate}.glow{animation:glimmer var(--glow) steps(4) infinite alternate}.sway{animation:sway var(--sway) steps(4) infinite alternate}.leaf{animation:fall var(--leaves) steps(14) infinite}.shadow{animation:shade var(--light) steps(6) infinite alternate}.late{animation-delay:-7s}@keyframes parallax{from{transform:translateX(-1px)}to{transform:translateX(1px)}}@keyframes lighting{from{opacity:.02}to{opacity:.18}}@keyframes breeze{from{transform:translateX(-5px)}to{transform:translateX(5px)}}@keyframes sparkle{0%,15%{opacity:0}70%,100%{opacity:1}}@keyframes glimmer{from{opacity:.35}to{opacity:1}}@keyframes sway{from{transform:translateX(-1px)}to{transform:translateX(1px)}}@keyframes fall{0%{transform:translate(-3px,-3px);opacity:0}10%{opacity:1}80%{opacity:1}100%{transform:translate(4px,18px);opacity:0}}@keyframes shade{from{opacity:.65}to{opacity:1}}';
    }

    function _motionSeconds(uint8 family, uint8 variant) internal pure returns (uint256) {
        if (family == 0) return variant == 0 ? 8 : variant == 1 ? 6 : variant == 2 ? 4 : 10;
        if (family == 1) return variant == 0 ? 3 : variant == 1 ? 2 : variant == 2 ? 4 : 5;
        if (family == 2) return variant == 0 ? 10 : variant == 1 ? 8 : variant == 2 ? 14 : 6;
        if (family == 3) return variant == 0 ? 6 : variant == 1 ? 4 : variant == 2 ? 8 : 3;
        if (family == 4) return variant == 0 ? 8 : variant == 1 ? 6 : variant == 2 ? 12 : 4;
        if (family == 5) return variant == 0 ? 5 : variant == 1 ? 3 : variant == 2 ? 7 : 4;
        if (family == 6) return variant == 0 ? 20 : variant == 1 ? 16 : variant == 2 ? 24 : 12;
        if (family == 7) return variant == 0 ? 4 : variant == 1 ? 3 : variant == 2 ? 6 : 5;
        revert("Invalid motion");
    }

    function _motionKey(uint8 family) internal pure returns (string memory) {
        if (family == 0) return "cloud";
        if (family == 1) return "stars";
        if (family == 2) return "leaves";
        if (family == 3) return "sway";
        if (family == 4) return "light";
        if (family == 5) return "glow";
        if (family == 6) return "depth";
        if (family == 7) return "float";
        revert("Invalid motion");
    }

    function motionStyle(uint16 ambience) external pure returns (string memory result) {
        result = ":root{";
        for (uint8 i; i < 8; i++) {
            result = string.concat(result, i == 0 ? "" : ";", "--", _motionKey(i), ":",
                _motionSeconds(i, uint8((ambience >> (i * 2)) & 3)).toString(), "s");
        }
        return string.concat(result, "}");
    }

    function _box(uint256 x, uint256 y, uint256 width, uint256 height, string memory color)
        internal pure returns (string memory)
    {
        width = (x + width) * 3 / 2 - x * 3 / 2;
        height = (y + height) * 3 / 2 - y * 3 / 2;
        x = x * 3 / 2;
        y = y * 3 / 2;
        return string.concat('<path fill="', color, '" d="M', x.toString(), ' ', y.toString(),
            'h', width.toString(), 'v', height.toString(), 'H', x.toString(), 'z"/>');
    }

    function _eyes(uint8 expression, uint256 left, uint256 right, uint256 y, string memory ink)
        internal pure returns (string memory)
    {
        if (expression == 1) return string.concat(_box(left, y, 2, 3, ink), _box(right, y + 2, 3, 1, ink));
        if (expression == 2) return string.concat(_box(left - 1, y, 6, 3, "#10141e"),
            _box(right - 1, y, 6, 3, "#10141e"), _box(left + 1, y, 2, 1, "#9be7e6"));
        if (expression == 3) return string.concat(_box(left, y, 3, 3, "#ffe078"),
            _box(right, y, 3, 3, "#ffe078"), _box(left + 1, y + 1, 1, 1, ink),
            _box(right + 1, y + 1, 1, 1, ink));
        return string.concat(_box(left, y, 2, 3, ink), _box(right, y, 2, 3, ink),
            _box(left, y, 1, 1, "#ffffff"), _box(right, y, 1, 1, "#ffffff"));
    }

    function _feet(uint8 species, string memory ink, string memory body) internal pure returns (string memory) {
        uint256 left = species == 3 ? 23 : 21;
        uint256 y = species == 2 ? 46 : 45;
        return string.concat(
            '<g class="foot-a">', _box(left, y, 6, 6, ink), _box(left + 1, y, 4, 4, body), '</g>',
            '<g class="foot-b">', _box(38, y, 6, 6, ink), _box(39, y, 4, 4, body), '</g>'
        );
    }

    function _cat(string memory body, string memory ink, uint8 expression) internal pure returns (string memory) {
        return string.concat(
            _box(45, 35, 5, 3, ink), _box(48, 31, 3, 5, ink), _box(47, 28, 3, 4, ink),
            _box(16, 15, 7, 12, ink), _box(39, 15, 7, 12, ink),
            _box(18, 17, 4, 9, body), _box(40, 17, 4, 9, body),
            _box(19, 20, 2, 4, "#f6a3b3"), _box(41, 20, 2, 4, "#f6a3b3"),
            _box(17, 25, 29, 20, ink), _box(19, 27, 25, 15, body),
            _box(23, 38, 17, 6, "#f5d8bd"), _eyes(expression, 24, 37, 31, ink),
            _box(30, 38, 3, 2, ink), _box(12, 38, 8, 1, ink), _box(43, 38, 8, 1, ink),
            _box(13, 41, 7, 1, ink), _box(43, 41, 7, 1, ink), _feet(0, ink, body)
        );
    }

    function _robot(string memory body, string memory ink, uint8 expression) internal pure returns (string memory) {
        return string.concat(
            '<g class="body">',
            _box(17, 18, 30, 24, ink), _box(19, 20, 26, 20, body),
            '<g class="sheen">', _box(20, 20, 23, 1, "#d5e5eb"), _box(19, 21, 1, 16, "#b9c6e4"), '</g>',
            _box(43, 22, 2, 18, ink), _box(21, 21, 1, 1, ink), _box(42, 21, 1, 1, ink),
            _box(16, 24, 3, 8, "#6bdce3"), _box(45, 24, 3, 8, "#6bdce3"),
            _box(22, 23, 20, 12, "#192a41"), _eyes(expression, 26, 36, 27, "#79e3e3"),
            _box(23, 33, 3, 1, "#80c9ab"), _box(28, 33, 2, 1, "#f0bd5e"),
            _box(25, 36, 14, 2, ink), _box(30, 36, 4, 1, "#f0bd5e"),
            _box(21, 41, 22, 4, ink), _box(23, 41, 18, 2, "#2b4767"),
            '<g class="arm-a">', _box(12, 27, 5, 11, ink), _box(13, 30, 3, 6, body), _box(11, 38, 5, 3, "#f0bd5e"), '</g>',
            '<g class="arm-b">', _box(47, 27, 5, 11, ink), _box(48, 30, 3, 6, body), _box(48, 38, 5, 3, "#f0bd5e"), '</g>',
            '</g>', _feet(1, ink, body)
        );
    }

    function _frog(string memory body, string memory ink, uint8 expression) internal pure returns (string memory) {
        return string.concat(
            _box(16, 17, 11, 12, ink), _box(37, 17, 11, 12, ink),
            _box(18, 19, 7, 8, body), _box(39, 19, 7, 8, body),
            _box(16, 26, 32, 20, ink), _box(18, 28, 28, 15, body),
            _box(22, 38, 20, 6, "#d0e5a5"), _eyes(expression, 21, 41, 22, ink),
            _box(22, 35, 3, 2, ink), _box(39, 35, 3, 2, ink),
            _box(25, 38, 14, 1, ink), _box(19, 39, 2, 2, "#f3a19c"),
            _box(43, 39, 2, 2, "#f3a19c"), _feet(2, ink, body)
        );
    }

    function _turtle(string memory body, string memory ink, uint8 expression) internal pure returns (string memory) {
        return string.concat(
            _box(12, 36, 6, 3, ink), _box(15, 39, 5, 2, ink),
            _box(17, 28, 30, 19, ink), _box(20, 25, 23, 4, ink),
            _box(20, 29, 25, 15, body), _box(25, 26, 15, 3, body),
            _box(29, 30, 3, 13, ink), _box(21, 36, 23, 2, ink),
            _box(23, 31, 4, 3, "#f1d48f"), _box(35, 31, 4, 3, "#f1d48f"),
            _box(46, 31, 11, 13, ink), _box(48, 29, 7, 3, ink),
            _box(48, 33, 9, 9, "#91d890"), _box(54, 36, 6, 5, "#91d890"),
            _box(55, 41, 5, 2, ink), _eyes(expression, 52, 57, 34, ink),
            _feet(3, ink, "#91d890")
        );
    }

    function render(uint8, string calldata body, string calldata ink, uint8 expression)
        external pure returns (string memory)
    {
        return _robot(body, ink, expression);
    }
}

